    const edit = path.match(/^\/notes\/(\d+)\/edit$/);
    if (edit && method === 'GET') return send(200, noteForm(requireNote(store.getNote(Number(edit[1])))));
    const deletion = path.match(/^\/notes\/(\d+)\/delete$/);
